import{_ as o,a0 as p,w as d,s as c,ao as l,I as n,x as s,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Linux 终端使用 inxi 命令获取各种系统信息 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 终端使用 inxi 命令获取各种系统信息 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 终端使用 inxi 命令获取各种系统信息 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 终端使用 inxi 命令获取各种系统信息 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20211215 Get All Kind of System Information in Linux Terminal With inxi","title":"在 Linux 终端使用 inxi 命令获取各种系统信息","tag":"202112","desc":""},"relativePath":"202112/20211215 Get All Kind of System Information in Linux Terminal With inxi.md","filePath":"[post].md"}'),r={name:"202112/20211215 Get All Kind of System Information in Linux Terminal With inxi.md"};function h(g,i,u,b,k,m){const e=p("Link");return d(),c("div",null,[i[18]||(i[18]=l(`<h1 id="在-linux-终端使用-inxi-命令获取各种系统信息" tabindex="-1">在 Linux 终端使用 inxi 命令获取各种系统信息 <a class="header-anchor" href="#在-linux-终端使用-inxi-命令获取各种系统信息" aria-label="Permalink to “在 Linux 终端使用 inxi 命令获取各种系统信息”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202112/17/134920bzuqfbwbqswcif33.jpg" alt=""></p><p><code>inix</code> 是一个用于获取 Linux 系统信息的终端命令。能够获取软件和硬件的详细信息，比如计算机型号、内核版本、发行版号以及桌面环境等信息，甚至可以读取主存模块占用主板的哪块 RAM 卡槽等详细信息。</p><p><code>inxi</code> 还可以用于监控系统中正在消耗 CPU 或者内存资源的进程。</p><p>在本文中，我将展示使用 <code>inxi</code> 命令获取系统信息的常用操作。</p><p>首先，我将展示下如何安装 <code>inxi</code> 命令。</p><h3 id="在-linux-上安装-inxi" tabindex="-1">在 Linux 上安装 inxi <a class="header-anchor" href="#在-linux-上安装-inxi" aria-label="Permalink to “在 Linux 上安装 inxi”">​</a></h3><p><code>inxi</code> 是一个非常流行的工具，所以在大多数 Linux 发行版仓库中都可以轻松获取到该工具。不过还没有流行到各大 Linux 发行版默认就安装了该软件，所以需要我们自己安装一下。</p><p>在 Ubuntu/Debian 发行版系统中，安装命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install inxi</span></span></code></pre></div><p>在 Fedora/RHEL8-based 等发行版中，安装命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install -y epel-release</span></span>
<span class="line"><span>sudo dnf install -y inxi</span></span></code></pre></div><p>在 <code>Arch Linux</code> 以及它的派生分支版本中，安装命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S inxi</span></span></code></pre></div><h3 id="使用-inxi-获取系统信息" tabindex="-1">使用 inxi 获取系统信息 <a class="header-anchor" href="#使用-inxi-获取系统信息" aria-label="Permalink to “使用 inxi 获取系统信息”">​</a></h3><p>你可以在终端运行 <code>inxi</code> 命令来总体浏览下系统信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi</span></span></code></pre></div><p>如下图所示，运行 <code>inxi</code> 命令可以简要浏览 CPU、时钟频率（<code>speed/min/max</code>）、内核（<code>Kernel</code>）、内存（<code>Mem</code>）、磁盘存储空间（<code>Storage</code>）、运行进程数量（<code>Procs</code>）以及 Shell 等信息。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/01_inxi.webp?resize=800%2C450&amp;ssl=1" alt="The default output of inxi command"></p><p>使用 <code>-b</code> 参数可以获取更为详细的系统信息。<code>-b</code> 参数会读取更多有关 CPU、驱动器、当前运行进程、主板 UEFI 版本、GPU、显示分辨率以及网络设备等详细信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -b</span></span></code></pre></div><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/02_inxi_flag_b.webp?resize=800%2C450&amp;ssl=1" alt="Detailed hardware and software information about machine as reported by inxi"></p><p>类似 <code>-b</code> 参数使用方法，<code>inxi</code> 还有许多其他的参数可供使用。你可以综合使用这些参数来获取你关心的信息。</p><p>让我们看几个实例。</p><h3 id="获取音频设备信息" tabindex="-1">获取音频设备信息 <a class="header-anchor" href="#获取音频设备信息" aria-label="Permalink to “获取音频设备信息”">​</a></h3><p>使用 <code>-A</code> 参数可以获取有关音频（输出）设备信息，包括物理音频（输出）设备、声音服务器以及音频驱动等详细信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -A</span></span></code></pre></div><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/03_inxi_flag_a.webp?resize=800%2C450&amp;ssl=1" alt="Output of inxi command when “-A” flag is used"></p><h3 id="获取电池信息" tabindex="-1">获取电池信息 <a class="header-anchor" href="#获取电池信息" aria-label="Permalink to “获取电池信息”">​</a></h3><p>使用 <code>-B</code> 参数，可以获取有关电池的信息（如果安装了电池）。你将读取到例如以 <code>Wh</code>（瓦特小时）为单位的当前电池电量和状况。</p><p>因为我使用的是台式机，所以这里仅仅作为一个示例，让我们看看使用 <code>inxi -B</code> 会输出什么。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Battery:   ID-1: BAT0 charge: 50.0 Wh (100.0%) condition: 50.0/50.0</span></span></code></pre></div><h3 id="获取-cpu-信息" tabindex="-1">获取 CPU 信息 <a class="header-anchor" href="#获取-cpu-信息" aria-label="Permalink to “获取 CPU 信息”">​</a></h3><p><code>-C</code> 参数用于获取有关 CPU 的详细信息。比如包括 CPU 缓存大小、频率（单位 <code>MHz</code>，如果有多核，会显示每个核心的频率）、核心数、CPU 型号以及 CPU 是 32 位还是 64 位。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -C</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/04_inxi_flag_c.webp?resize=800%2C450&amp;ssl=1" alt="Detailed CPU information displayed by inxi"></p><p>注意，如果是在虚拟机中使用 <code>inix -C</code>，<code>inxi</code> 读取到的 <code>CPU</code> 的最大和最小频率可能异常。下面是一个在四核 Debian 11 虚拟机中使用 <code>-C</code> 参数的示例输出。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/05_inxi_flag_c_vm.webp?resize=800%2C396&amp;ssl=1" alt="An example output of using the “-C” flag in a Virtual Machine"></p><h3 id="获取更多的系统信息" tabindex="-1">获取更多的系统信息 <a class="header-anchor" href="#获取更多的系统信息" aria-label="Permalink to “获取更多的系统信息”">​</a></h3><p>使用 <code>-F</code> 参数可以获取更详细的系统信息（类似 <code>-b</code> 参数，但会更为详细）。几乎囊括了所有层次的系统信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -F</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/06_inxi_flag_f.webp?resize=800%2C450&amp;ssl=1" alt=""></p><h3 id="获取图形显示相关信息" tabindex="-1">获取图形显示相关信息 <a class="header-anchor" href="#获取图形显示相关信息" aria-label="Permalink to “获取图形显示相关信息”">​</a></h3><p><code>-G</code> 参数可以获取和图形相关的信息。</p><p>它会显示所有的图形设备（GPU）、正在使用的 GPU 驱动（有助于检查是否使用 Nvidia 驱动还是 nouveau 驱动）、显示输出分辨率和驱动程序版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -G</span></span></code></pre></div><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/07_inxi_flag_g.webp?resize=800%2C450&amp;ssl=1" alt=""></p><h3 id="获取运行进程信息" tabindex="-1">获取运行进程信息 <a class="header-anchor" href="#获取运行进程信息" aria-label="Permalink to “获取运行进程信息”">​</a></h3><p><code>-I</code> 参数（大写字母 <code>i</code>）显示正在运行的进程、当前 shell 、内存（内存使用情况）以及 <code>inxi</code> 版本号等信息。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/inxi-get-running-process-info.png?resize=768%2C272&amp;ssl=1" alt="inxi get running process info"></p><h3 id="获取内存信息" tabindex="-1">获取内存信息 <a class="header-anchor" href="#获取内存信息" aria-label="Permalink to “获取内存信息”">​</a></h3><p>可能你已经猜到了，<code>-m</code> 参数可以获取与内存相关的信息。</p><p>它读取了如总可用内存、最大内存容量（硬件或 CPU 支持的）、主板物理内存插槽数、是否存在 ECC、插入的内存插槽，以及枚举每个插槽中运行的内存模块的大小和运行速度等信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -m</span></span></code></pre></div><p>要使用 <code>-m</code> 参数获取更详细的信息，例如最大容量、每个插槽的内存模块信息等，需要超级用户权限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo inxi -m</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/08_inxi_flag_m.webp?resize=800%2C450&amp;ssl=1" alt=""></p><p>如果只是希望简短的输出内存信息，可以使用 <code>-memory-short</code> 参数。</p><p>使用 <code>-memroy-short</code> 参数将会只显示总内存以及当前已使用的内存量。</p><h3 id="查看正在使用的包存储库" tabindex="-1">查看正在使用的包存储库 <a class="header-anchor" href="#查看正在使用的包存储库" aria-label="Permalink to “查看正在使用的包存储库”">​</a></h3><p>当使用 <code>-r</code> 参数时，会列举当前正在使用的包管理仓库或者更新本地仓库缓存中的所有存储库列表。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/package-repo-info-with-inxi.png?resize=800%2C339&amp;ssl=1" alt="List of repositories in use"></p><h3 id="获取-raid-设备信息" tabindex="-1">获取 RAID 设备信息 <a class="header-anchor" href="#获取-raid-设备信息" aria-label="Permalink to “获取 RAID 设备信息”">​</a></h3><p><code>-R</code> 参数用于获取所有 RAID 设备相关信息。</p><p>令人惊喜的是，它甚至显示了有关 ZFS RAID（默认情况下，多数 Linux 系统不包含该文件系统）的信息。它显示了 RAID 设备上文件系统的详细信息、状态（包含离线状态、总大小和可用大小等）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -R</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/09_inxi_flag_r.webp?resize=800%2C450&amp;ssl=1" alt=""></p><h3 id="在-linux-终端中查询天气-对-这是可以的" tabindex="-1">在 Linux 终端中查询天气（对，这是可以的） <a class="header-anchor" href="#在-linux-终端中查询天气-对-这是可以的" aria-label="Permalink to “在 Linux 终端中查询天气（对，这是可以的）”">​</a></h3><p>利用 <code>-W</code> 参数，你可以查询地球上任何地方的天气情况。</p><p><code>-W</code> 参数后面，需要携带以下中的任一一个体现位置的信息</p><ul><li>邮政编码</li><li>纬度</li><li>城市（及州）、国家（不能含有空格，使用 “+” 替换空格）</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -W Baroda,India</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/12_inxi_flag_w.webp?resize=800%2C450&amp;ssl=1" alt="Use of the “-W” flag with inxi followed by the city,country location descriptor"></p><h3 id="监控系统资源使用情况" tabindex="-1">监控系统资源使用情况 <a class="header-anchor" href="#监控系统资源使用情况" aria-label="Permalink to “监控系统资源使用情况”">​</a></h3><p><code>inxi</code> 除了提供有关已安装的硬件和驱动的信息外，还可以用于资源监控。</p><p>使用 <code>-t</code> 参数可以显示进程信息。你还可以可选项 <code>-c</code> （用于 CPU）和 <code>-m</code>（用于内存）。这些选项结合使用可以按指定数量列出进程信息。</p><p>下面是一些使用 <code>-t</code> 参数监控资源信息的示例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -t</span></span></code></pre></div><p>命令 <code>inxi -t</code> 默认效果等同于 <code>inxi -t cm5</code> 的效果。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/10_inxi_flag_t.webp?resize=800%2C450&amp;ssl=1" alt="No difference in output of “inti -t” and “inxi -t cm5”"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -t cm10</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/11_inxi_flag_t_cm10.webp?resize=800%2C450&amp;ssl=1" alt=""></p>`,82)),n("p",null,[i[1]||(i[1]=s("偶尔需要监控资源使用情况时，该工具挺管用。如果需要更多的资源监控功能，则推荐使用 ",-1)),a(e,{href:"https://itsfoss.com/linux-system-monitoring-tools/"},{default:t(()=>[...i[0]||(i[0]=[s("专用系统资源监控工具",-1)])]),_:1}),i[2]||(i[2]=s("。",-1))]),i[19]||(i[19]=l('<h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>对于需要诊断计算机问题以及获取那些并不熟悉的软硬件信息的人来说，<code>inxi</code> 工具是十分便利且有用的。它能识别那些消耗 CPU、内存的进程；可以检查是否安装了合适的图形驱动程序、主板 UEFI/BIOS 是否需要更新等等。</p><p>事实上，在 <code>inxi</code> 开源社区论坛上，我们要求那些寻求帮助的成员提供 <code>inxi</code> 命令输出内容以便判断他们当前正在使用什么样的系统环境。</p><p>我知道也有其他的工具可以读取 Linux 上的硬件信息，不过 <code>inxi</code> 同时能读取硬件和软件信息，这也是我喜欢它的地方所在。</p><p>你使用 <code>inxi</code> 或者其他工具么？欢迎在评论区留言分享交流。</p><hr>',6)),n("p",null,[i[4]||(i[4]=s("via: ",-1)),a(e,{href:"https://itsfoss.com/inxi-system-info-linux/"},{default:t(()=>[...i[3]||(i[3]=[s("https://itsfoss.com/inxi-system-info-linux/",-1)])]),_:1})]),n("p",null,[i[9]||(i[9]=s("作者：",-1)),a(e,{href:"https://itsfoss.com/author/pratham/"},{default:t(()=>[...i[5]||(i[5]=[s("Pratham Patel",-1)])]),_:1}),i[10]||(i[10]=s(" 选题：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...i[6]||(i[6]=[s("lujun9972",-1)])]),_:1}),i[11]||(i[11]=s(" 译者：",-1)),a(e,{href:"https://github.com/jrglinux"},{default:t(()=>[...i[7]||(i[7]=[s("jrglinux",-1)])]),_:1}),i[12]||(i[12]=s(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...i[8]||(i[8]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[15]||(i[15]=s("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[13]||(i[13]=[s("LCTT",-1)])]),_:1}),i[16]||(i[16]=s(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...i[14]||(i[14]=[s("Linux中国",-1)])]),_:1}),i[17]||(i[17]=s(" 荣誉推出",-1))])])}const y=o(r,[["render",h]]);export{C as __pageData,y as default};
